<?php
namespace App\Http\Controllers;
use App\Models\Attendance; use App\Models\Student; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class AttendanceController extends Controller {
 public function index(Request $request){ $date=$request->input('date',now()->toDateString()); $q=Student::where('status','Active'); foreach(['department','technology','semester','session','shift'] as $f) if($request->filled($f)) $q->where($f,$request->$f); $students=$q->orderBy('student_id')->get(); $records=Attendance::whereDate('attendance_date',$date)->whereIn('student_id',$students->pluck('id'))->get()->keyBy('student_id'); $departments=Student::select('department')->distinct()->orderBy('department')->pluck('department'); $technologies=Student::select('technology')->distinct()->orderBy('technology')->pluck('technology'); $semesters=Student::select('semester')->distinct()->orderBy('semester')->pluck('semester'); $sessions=Student::select('session')->distinct()->orderBy('session')->pluck('session'); return view('attendance.index',compact('date','students','records','departments','technologies','semesters','sessions')); }
 public function store(Request $request){ $data=$request->validate(['attendance_date'=>'required|date|before_or_equal:today','attendance'=>'required|array|min:1','attendance.*'=>'required|in:Present,Absent,Late,Leave']); DB::transaction(function() use($data){ foreach($data['attendance'] as $studentId=>$status){ if(!Student::whereKey($studentId)->where('status','Active')->exists()) continue; Attendance::updateOrCreate(['student_id'=>$studentId,'attendance_date'=>$data['attendance_date']],['status'=>$status]); }}); return back()->with('success',count($data['attendance']).' জন শিক্ষার্থীর হাজিরা সংরক্ষণ হয়েছে।'); }
 public function report(Request $request){ $from=$request->input('from',now()->startOfMonth()->toDateString()); $to=$request->input('to',now()->toDateString()); $rows=Attendance::with('student')->whereBetween('attendance_date',[$from,$to])->latest('attendance_date')->paginate(30)->withQueryString(); return view('attendance.report',compact('rows','from','to')); }
}
